import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.D0gLf8u5.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"about/faq.md","filePath":"about/faq.md","lastUpdated":null}'),n={name:"about/faq.md"};function i(l,a,h,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="云族纪和普通族谱软件有什么区别" tabindex="-1">云族纪和普通族谱软件有什么区别？ <a class="header-anchor" href="#云族纪和普通族谱软件有什么区别" aria-label="Permalink to &quot;云族纪和普通族谱软件有什么区别？&quot;">​</a></h2><p>普通族谱软件画的是一棵父系树，云族纪记录的是一张<strong>关系网</strong>——支持配偶、外亲、跨家族连接，更接近真实的家族关系。</p><h2 id="我的数据安全吗" tabindex="-1">我的数据安全吗？ <a class="header-anchor" href="#我的数据安全吗" aria-label="Permalink to &quot;我的数据安全吗？&quot;">​</a></h2><p>云族纪是<strong>私有部署</strong>的，每个家族的数据存在自己的 uniCloud 空间里，不在公共服务器上。不上架、不开放公网，只有你邀请的人能访问。</p><h2 id="支持多少人" tabindex="-1">支持多少人？ <a class="header-anchor" href="#支持多少人" aria-label="Permalink to &quot;支持多少人？&quot;">​</a></h2><p>目前免费 uniCloud 额度足够几十到上百人使用。如果家族规模上千，需要升级云空间套餐。</p><h2 id="支持-gedcom-格式吗" tabindex="-1">支持 GEDCOM 格式吗？ <a class="header-anchor" href="#支持-gedcom-格式吗" aria-label="Permalink to &quot;支持 GEDCOM 格式吗？&quot;">​</a></h2><p>支持。云族纪可以把 GEDCOM 文件转换为 CSV 格式后导入，也支持导出为 CSV。GEDCOM 7.0 和 5.5.1 都兼容。</p><h2 id="可以在手机上用吗" tabindex="-1">可以在手机上用吗？ <a class="header-anchor" href="#可以在手机上用吗" aria-label="Permalink to &quot;可以在手机上用吗？&quot;">​</a></h2><p>可以。基于 uni-app 开发，一套代码支持微信小程序、App、H5。自家人在手机上就能看族谱。</p><h2 id="录错了怎么办" tabindex="-1">录错了怎么办？ <a class="header-anchor" href="#录错了怎么办" aria-label="Permalink to &quot;录错了怎么办？&quot;">​</a></h2><p>云族纪的所有写操作都有归档快照。添加、修改、删除、导入都可以撤销，撤销就是恢复到操作前的状态。</p><h2 id="支持近亲-同族婚姻吗" tabindex="-1">支持近亲/同族婚姻吗？ <a class="header-anchor" href="#支持近亲-同族婚姻吗" aria-label="Permalink to &quot;支持近亲/同族婚姻吗？&quot;">​</a></h2><p>支持。云族纪不限制婚姻关系，按真实情况记录即可。系统会提示近亲关系，但不强制阻止。</p>',15)])])}const _=e(n,[["render",i]]);export{u as __pageData,_ as default};
